def apply(inputs, premises):
    setting_ok = inputs["service_setting"] in premises["covered_settings"]
    year_ok = False
    for payment_year in inputs["remuneration_years"]:
        if int(payment_year) == inputs["claim_year"] or int(payment_year) == inputs["claim_year"] - premises["preceding_year_offset"]:
            year_ok = True
    threshold_ok = inputs["remuneration_is_expressly_cash"] and inputs["remuneration_amount"] >= premises["cash_remuneration_threshold"]
    if inputs["service_is_domestic"] and setting_ok and year_ok and threshold_ok:
        return {"answer": "Entailment"}
    return {"answer": "Contradiction"}
